local W = 256 -- 0x100
local H = 170 -- 0xaa
local Black = 0x8000
---@type int[][]
local _orig = {}
---@type int[][]
local _vs = {}

for i = 1, H do
    local line = DATA[i]
    assert(#line == W*4, "WRONG WIDTH")
    local v = htob(line)
    local ret = {}
    local ret2 = {}
    for j = 1, W do
        ret[j] = v[2*j-1] | (v[2*j] << 8)
        ret2[j] = ret[j]
    end
    _orig[i] = ret
    _vs[i] = ret2
end

---@param x int
---@param y int
---@return int
local function orig(x, y)
    return _orig[y+1][x+1]
end

local function pos(x, y)
    return lib.pos.Raster(x, y, 0x100)*2 + 0x06081600
end
local function pos2(x, y)
    return lib.pos.Raster(x, y, 0x100)*2 + 0x060a1600
end
---@param x int
---@param y int
---@return int
local function get(x, y)
    return _vs[y+1][x+1]
end

local function write()
    for y = 0, H-1 do
        for x = 0, W-1 do
            local v = get(x, y)
            w16(pos(x, y), v)
            w16(pos2(x, y), v)
        end
    end
end

---@param x int
---@param y int
---@param v int
local function set(x, y, v)
    _vs[y+1][x+1] = v
end

---@alias GoFun fun(x: int, y: int): int? | ( (fun(x: int, y: int): int?)[] )

---@type (fun(obj: {time: int}): GoFun)[]
local presets = {}
local presets_idx = 1
local is_first = true
local presets_time = 0
---@type (fun(x: int, y: int))[]
local tmp_func = nil

---@type {time: number, update: fun()?, reset: boolean}
local time_obj = {time = 0, update = nil, reset = true}
---@param v number
local function getTimeInt(v)
    return round(clamp(v, 0, 100) * 60)
end

---@type (fun(obj: {time: number, update: fun()?, reset: boolean}): fun(x: int, y: int))[]
local presets_reserved = {}

local is_in_lib = true

---@param func fun(obj: {time: number, update: fun()?}, reset: boolean): GoFun
---@overload fun()
local function addPreset(func)
    if is_in_lib then
        table.insert(presets_reserved, func)
    elseif func then
        table.insert(presets, func)
    else
        for _, f in pairs(presets_reserved) do
            table.insert(presets, f)
        end
        presets_reserved = {}
    end
end
local total_time = 0

local function update()
    if time_obj.update then time_obj.update() end
    total_time = total_time + 1 CLS()
    printf("time: %f", total_time/60)
    if is_first then
        if #presets == 0 then
            table.insert(presets, function()end)
        end
        is_first = false
        time_obj.update = nil
        time_obj.time = 5.0
        time_obj.reset = true
        local f = presets[1](time_obj)
        if not f then
            tmp_func = {function()end}
        elseif type(f) == "function" then
            tmp_func = {f}
        else tmp_func = f
        end
        presets_time = getTimeInt(time_obj.time)
    end
    if #presets < presets_idx then return end
    if time_obj.reset then
        for y = 0, H-1 do
            for x = 0, W-1 do
                set(x, y, orig(x, y))
            end
        end
    end
    for _, f in pairs(tmp_func) do
        local __vs = {}
        for y = 0, H-1 do
            local __v = {}
            for x = 0, W-1 do
                __v[x] = f(x, y) or get(x, y)
            end
            __vs[y] = __v
        end
        for y = 0, H-1 do
            for x = 0, W-1 do
                set(x, y, __vs[y][x])
            end
        end
    end
    write()
    presets_time = presets_time - 1
    if presets_time <= 0 then
        presets_idx = presets_idx + 1
        if #presets >= presets_idx then
            time_obj.update = nil
            time_obj.time = 5.0
            time_obj.reset = true
            local f = presets[presets_idx](time_obj)
            if not f then
                tmp_func = {function()end}
            elseif type(f) == "function" then
                tmp_func = {f}
            else tmp_func = f
            end
            presets_time = getTimeInt(time_obj.time)
        end
    end
end

local G = {addPreset = addPreset}

-- ミサワ？顔
G.addPreset(function(obj)
    obj.time = 4.0
-- 左目の範囲
local xst = 130
local xed = 165
local yst = 0
local yed = 27

local xst2 = 80
local xed2 = 115
local yed2 = 40
return {
function(x, y)
    if within(x, xst2, xed2) and within(y, yst, yed2) then
        return orig(xst+xed2-x, y)
    end
end,
function(x, y)
    if within(x, 120, 155) and within(y, 10, 37) then
        return get(x-120+xst, y-10)
    elseif within(x, xst, xed) and within(y, yst, yed) then
        return orig(144, 0)
    end
    if within(x, 84, 119) and within(y, 10, 37) then
        return get(x-4, y-10)
    elseif within(x, xst2, xed2) and within(y, yst, yed) then
        return orig(144, 0)
    end
    if within(x, 100, 144) and within(y, 45, 53) then
        return orig(x, y+15)
    elseif within(x, 100, 144) and within(y, 54, 71) then
        return orig((x-120)//2+120, ilerp(77, 79, invlerp(y, 54, 70)))
    end
end,
}
end)

