    end
end,
}
end)

-- 真四角
G.addPreset(function(obj)
    local xst = 80
    local xed = 165
    local yst = 0
    local yed = 85
    return function(x, y)
        if y >= yst and within(x, xst, xed) then
            local _y = ilerp(yst, yed, invlerp(y, yst, H-1))
            local ct = (xed+xst)//2
            local _x = x
            _x = _x - ct
            local yt = invlerp(_y, yst, yed)
            yt = 1-yt
            _x = round(_x * yt) + ct
            _x = clamp(_x, xst, xed)
            return orig(clamp(_x, xst, xed), clamp(_y, yst, yed))
        end
    end
end)

--アゴパカパカ
G.addPreset(function(obj)
local xst = 80
local xed = 165
local yst = 40
local yed = 85
local V = ValueUpdater(45, -40, 20, "pingpong")
V.i = 22
obj.update = function() V() end
return function(x, y)
    if y >= yst and within(x, xst, xed) then
        local _y = ilerp(yst, yed, invlerp(y, yst, H-1))
        local ct = (xed+xst)//2
        local _x = x
        local ct = (xed+xst)//2
        _x = _x + (_x >= ct and 1 or -1) * (
            invlerp(y, yst, H-1)*V.v
        )
        _x = round(_x)
        return orig(clamp(_x, xst, xed), clamp(_y, yst, yed))
    end
end
end)

-- 目が点
G.addPreset(function(obj)
-- 左目の範囲
local xst = 130
local xed = 165
local yst = 0
local yed = 27

local xst2 = 80
local xed2 = 115
local yed2 = 40
return {
function(x, y)
    if within(x, xst2, xed2) and within(y, yst, yed2) then
        return orig(xst+xed2-x, y)
    end
end,
function(x, y)
    if within(y, yed-5, yed) then
        if within(x, xst2, xst2+5) then
            return
        end
        if within(x, xed-5, xed) then
            return
        end
    end
    if not within(y, yst+13, yed) then return end
    local dist_x, dist_y
    dist_y = math.abs(y - (yed+yst+13)/2)
    if within(x, xst, xed) then
        dist_x = math.abs(x - (xed+xst)/2)
        local d = dist_x*dist_x + dist_y*dist_y
        if d < 9 then return Black end
        return orig(144, 0)
    elseif within(x, xst2, xed2) then
        dist_x = math.abs(x - (xed2+xst2)/2)
        local d = dist_x*dist_x + dist_y*dist_y
        if d < 9 then return Black end
        return orig(144, 0)
    end
end,
}
end)


-- アゴのばし
G.addPreset(function(obj)
local xst = 80
local xed = 165
local yst = 40
local yed = 85
local cc1 = Cnt(50, 2)
local current_1 = 1.0
local target_1 = 1.0
local cnt = 1
obj.update = function()
    if cc1() then
        cnt = cnt + 1
    end
    target_1 = (cc1.i == 0 and 1 or -1) * cnt
    current_1 = lerp(current_1, target_1, 0.1)
end
return function(x, y)
    if y >= yst and within(x, xst, xed) then
        local _y = ilerp(yst, yed, invlerp(y, yst, H-1))
        local ct = (xed+xst)//2
        local _x = x
        local y2 = _y + round(math.abs(_x - ct) * 0.5 * current_1)
        if within(y, yst, yst+30) then
            y2 = ilerp(_y, y2, invlerp(y, yst, yst+30))
        end
        return orig(clamp(_x, xst, xed), clamp(y2, yst, yed))
    end
end
end)

