-- げろ！ゲーチスの
G.addPreset(function(obj)
-- 左目の範囲
local xst = 130
local xed = 165
local yst = 0
local yed = 27

local xst2 = 80
local xed2 = 115
local yed2 = 40
local D = 4
local r = RC(5)
local c = Cnt(60)
obj.update = function()
    c()
    if r() then
        while true do
            local v = rand(3, 7)
            if D ~= v then
                D = v break
            end
        end
    end
end
return {
function(x, y)
    if not within(y, 13, 22) then return end
    if not within(x, xst, xed) and not within(x, xst2, xed2) then return end
    if within(x, 150, 155) and within(y, 14, 20) then 
        local _y = y + D
        if within(_y, 16, 22) then
            return get(x, _y)
        end
        return get(155, 21) -- 明るい白
        -- return get(90, 17) -- 暗い白
    end
    if within(x, 147, 149) and within(y, 15, 20) then 
        local _y = y + D
        if within(_y, 16, 22) then
            return get(x, _y)
        end
        return get(155, 21) -- 明るい白
    end
    if within(x, 141, 146) and within(y, 16, 20) then 
        local _y = y + D
        if within(_y, 16, 22) then
            return get(x, _y)
        end
        return get(155, 21) -- 明るい白
    end
    if within(x, 141, 155) and within(y, 21, 22) then 
        return get(155, 21) -- 明るい白
    end
end,
function(x, y)
    if within(x, xst2, xed2) and within(y, yst, yed2) then
        return get(xst+xed2-x, y)
    end
end,
function(x, y)
    if y >=67 and within(x, 110, 135) then
        local __y = (math.floor((y-67)/8) - c.i) % 30
        return get(x, __y+67) & 0xf9c2
    end
end
}
end)

-- ゲーチス大回転
G.addPreset(function(obj)
obj.time = 30
local xst = 80
local xed = 165
local yst = 0
local yed = 85
local sin, cos = 0 ,1
local scl = 1.0
local theta = 0
obj.update = function()
    -- local __x = t.i*2/t.n
    theta = theta + 0.02
    scl = scl+0.01
    sin = math.sin(scl*theta*0.5*math.pi)
    cos = math.cos(scl*theta*0.5*math.pi)
end
return {
function(x, y)
    if y >= yst and within(x, xst, xed) then
        local _y = ilerp(yst, yed, invlerp(y, yst, H-1))
        local ct = (xed+xst)//2
        local _x = x
        _x = _x - ct
        local yt = invlerp(_y, yst, yed)
        yt = 1-yt
        _x = round(_x * yt) + ct
        _x = clamp(_x, xst, xed)
        return orig(clamp(_x, xst, xed), clamp(_y, yst, yed))
    end
end,
function(x, y)
    local x2, y2 = x, y
    local _x, _y = x-W//2, y//2-H//2
    x2 = round(_x*sin + _y*cos)
    y2 = round(_x*cos - _y*sin)
    x2 = clamp(x2+W//2, 0, W-1)
    y2 = clamp(y2+H//2, 0, H-1)
    return get(x2, y2)
end
}
end)









